import numpy as np

# 距離を計算する関数
def calculate_distance(point1, point2):
    return np.linalg.norm(point1 - point2)

def main(N, points):
    for i in range(N):
        far_d, far_id = -1, -1
        for j in range(N):
            if i == j: continue
            d = calculate_distance(points[i], points[j])
            if d > far_d:
                far_d, far_id = d, j + 1
            elif d == far_d:
                far_id = min(far_id, j + 1)
        print(far_id)
